    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] birth = new long[n], death = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); birth[i] = (long) in.nval;
            in.nextToken(); death[i] = (long) in.nval;
        }
        long[] r = maxPopulation(birth, death);
        System.out.println(r[0] + " " + r[1]);
    }
}

