def gen(rng):
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(f'{b} {d}' for b, d in ps)
    tests = [
        fmt([(1, 2)]),
        fmt([(1, 5)] * 4),
        fmt([(1, 3), (3, 5)]),
        fmt([(1, 10**9), (2, 10**9)]),
        fmt([(5, 10), (10, 15), (2, 6)]),
        fmt([(1, 3), (2, 4), (3, 5), (4, 6)]),
        fmt([(7, 8), (7, 8), (9, 10)]),
    ]
    def person(hi):
        b = rng.randint(1, hi - 1)
        return (b, rng.randint(b + 1, hi))
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            hi = rng.choice([5, 10, 30])
            tests.append(fmt([person(hi) for _ in range(n)]))
    big = []
    for _ in range(100000):
        b = rng.randint(1, 10**9 - 1)
        big.append((b, rng.randint(b + 1, 10**9)))
    tests.append(fmt(big))
    tests.append(fmt([person(1000) for _ in range(100000)]))
    tests.append(fmt([(rng.randint(1, 5 * 10**8), rng.randint(5 * 10**8 + 1, 10**9)) for _ in range(100000)]))
    tests.append(fmt([(b, b + 1) for b in (rng.randint(1, 10**9 - 1) for _ in range(100000))]))
    return tests
